<?php
require_once __DIR__.'/../db.php';require_once __DIR__.'/../functions.php';require_admin();
$notice='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 $action=$_POST['action']??'';
 if($action==='generate'){
  $label=trim($_POST['label']??'');$duration=$_POST['duration']??'1day';
  if($label==='')$error='Enter a name or label for this access code.';
  else{$raw='LNF-'.strtoupper(bin2hex(random_bytes(4))).'-'.strtoupper(bin2hex(random_bytes(2)));$hash=hash('sha256',$raw);$expires=$duration==='forever'?null:date('Y-m-d H:i:s',time()+86400);$stmt=$conn->prepare('INSERT INTO access_codes(code_hash,code_label,expires_at) VALUES(?,?,?)');$stmt->bind_param('sss',$hash,$label,$expires);$stmt->execute();$_SESSION['new_access_code']=$raw;$notice='Access code created. Copy it now; it is shown only once.';}
 }elseif($action==='revoke'){
  $id=(int)($_POST['id']??0);$stmt=$conn->prepare('UPDATE access_codes SET is_revoked=1 WHERE id=?');$stmt->bind_param('i',$id);$stmt->execute();$notice='Access code revoked.';
 }elseif($action==='delete_item'){
  $id=(int)($_POST['id']??0);$stmt=$conn->prepare('DELETE FROM lost_found_items WHERE id=?');$stmt->bind_param('i',$id);$stmt->execute();$notice='Item report deleted.';
 }elseif($action==='status'){
  $id=(int)($_POST['id']??0);$status=$_POST['status']??'Lost';if(in_array($status,['Lost','Found','Returned'],true)){$stmt=$conn->prepare('UPDATE lost_found_items SET status=? WHERE id=?');$stmt->bind_param('si',$status,$id);$stmt->execute();$notice='Item status updated.';}
 }
}
if(isset($_GET['q'])&&$_GET['q']!==''){$q='%'.trim($_GET['q']).'%';$stmt=$conn->prepare('SELECT * FROM lost_found_items WHERE item_name LIKE ? OR reporter_name LIKE ? OR location LIKE ? ORDER BY created_at DESC LIMIT 200');$stmt->bind_param('sss',$q,$q,$q);$stmt->execute();$items=$stmt->get_result();}else{$items=$conn->query('SELECT * FROM lost_found_items ORDER BY created_at DESC LIMIT 200');}
$codes=$conn->query('SELECT * FROM access_codes ORDER BY created_at DESC LIMIT 100');
$counts=$conn->query("SELECT COUNT(*) total,SUM(status='Lost') lost_count,SUM(status='Found') found_count,SUM(status='Returned') returned_count FROM lost_found_items")->fetch_assoc();
$newCode=$_SESSION['new_access_code']??'';unset($_SESSION['new_access_code']);
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Admin Dashboard · Lost &amp; Found</title><link rel="stylesheet" href="../assets/style.css"><link rel="stylesheet" href="../assets/dashboard-theme.css"><style>.notice{background:#123c35;color:#9cf0d0;padding:12px;border-radius:8px;margin:12px 0}.error{background:#48202d;color:#ffc2d0;padding:12px;border-radius:8px;margin:12px 0}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse;min-width:750px}th,td{text-align:left;padding:12px;border-bottom:1px solid var(--line);vertical-align:top}th{font-size:11px;color:var(--muted)}.code{font:700 15px monospace;background:#080e1b;border:1px dashed #4386ff;padding:12px;border-radius:8px;word-break:break-all}.inline{display:flex;gap:8px;align-items:center;flex-wrap:wrap}</style></head><body><header class="topbar"><a class="brand" href="dashboard.php"><span class="brand-icon">⌕</span><span><b>Lost &amp; Found Admin</b><small>Management dashboard</small></span></a><div class="top-actions"><span class="muted small"><?=e($_SESSION['admin_username']??'Administrator')?></span><a class="btn secondary" href="logout.php">Sign out</a></div></header><main class="main-wrap wide"><div class="page-heading"><div><p class="eyebrow">ADMINISTRATION</p><h1>System overview</h1><p class="muted">Review reports, update item statuses, and manage student access.</p></div><a class="btn secondary" href="../report.php">View user dashboard ↗</a></div>
<div class="stats-grid"><div class="stat"><span>Total reports</span><b><?= (int)$counts['total']?></b></div><div class="stat"><span>Lost</span><b><?= (int)$counts['lost_count']?></b></div><div class="stat"><span>Found</span><b><?= (int)$counts['found_count']?></b></div><div class="stat"><span>Returned</span><b><?= (int)$counts['returned_count']?></b></div></div>
<?php if($notice):?><div class="notice"><?=e($notice)?></div><?php endif;?><?php if($error):?><div class="error"><?=e($error)?></div><?php endif;?><?php if($newCode):?><section class="panel section-panel"><h2>New access code — copy it now</h2><p class="muted">This raw code will not be displayed again.</p><div class="code" id="new-code"><?=e($newCode)?></div><button class="btn primary" style="margin-top:12px" onclick="navigator.clipboard.writeText(document.getElementById('new-code').innerText)">Copy code</button></section><?php endif;?>
<section class="panel section-panel"><h2>Generate access code</h2><p class="muted">Create a code for a student or staff member.</p><form method="post" class="form-grid"><input type="hidden" name="action" value="generate"><div><label>Student name or label</label><input name="label" required placeholder="e.g. Student Name / Section"></div><div><label>Access duration</label><select name="duration"><option value="1day">1 day</option><option value="forever">No expiration</option></select></div><div class="full-span"><button class="btn primary">Generate code</button></div></form></section>
<section class="panel section-panel"><h2>Item reports</h2><form method="get" class="inline" style="margin:15px 0"><input name="q" value="<?=e($_GET['q']??'')?>" placeholder="Search item, reporter, or location" style="max-width:400px"><button class="btn primary">Search</button><a class="btn secondary" href="dashboard.php">Reset</a></form><div class="table-wrap"><table><thead><tr><th>Item</th><th>Reporter / Contact</th><th>Type &amp; location</th><th>Date</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php while($it=$items->fetch_assoc()):?><tr><td><b><?=e($it['item_name'])?></b><div class="muted small"><?=e($it['category'])?></div><div class="muted small"><?=e($it['description'])?></div></td><td><?=e($it['reporter_name'])?><div class="muted small"><?=e($it['contact_info'])?></div></td><td><?=e($it['item_type'])?><div class="muted small"><?=e($it['location'])?></div></td><td><?=e($it['date_reported'])?></td><td><form method="post" class="inline"><input type="hidden" name="action" value="status"><input type="hidden" name="id" value="<?=$it['id']?>"><select name="status"><?php foreach(['Lost','Found','Returned'] as $s):?><option <?=$it['status']===$s?'selected':''?>><?=$s?></option><?php endforeach;?></select><button class="btn secondary small-btn">Save</button></form></td><td><form method="post" onsubmit="return confirm('Delete this item report?')"><input type="hidden" name="action" value="delete_item"><input type="hidden" name="id" value="<?=$it['id']?>"><button class="btn danger small-btn">Delete</button></form></td></tr><?php endwhile;?></tbody></table></div></section>
<section class="panel section-panel"><h2>Access code management</h2><p class="muted">Revoke codes that should no longer be able to sign in.</p><div class="table-wrap"><table><thead><tr><th>Label</th><th>Created</th><th>Expires</th><th>Last used</th><th>Status</th><th>Action</th></tr></thead><tbody><?php while($c=$codes->fetch_assoc()):$expired=$c['expires_at']!==null&&strtotime($c['expires_at'])<time();?><tr><td><?=e($c['code_label']??'—')?></td><td><?=e($c['created_at'])?></td><td><?=$c['expires_at']?e($c['expires_at']):'Never'?></td><td><?=e($c['last_used_at']??'Never')?></td><td><?=$c['is_revoked']?'Revoked':($expired?'Expired':'Active')?></td><td><?php if(!$c['is_revoked']&&!$expired):?><form method="post" onsubmit="return confirm('Revoke this access code?')"><input type="hidden" name="action" value="revoke"><input type="hidden" name="id" value="<?=$c['id']?>"><button class="btn danger small-btn">Revoke</button></form><?php else:?>—<?php endif;?></td></tr><?php endwhile;?></tbody></table></div></section></main></body></html>